WITH filtered AS (SELECT *, DAY(sale_date) AS sale_date_day FROM store_sales WHERE sale_date > DATE '2023-03-21') SELECT *, PERCENT_RANK() OVER (PARTITION BY store_id ORDER BY units DESC) AS units_percent_rank, SUM(sale_date_day) OVER (PARTITION BY store_id ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sale_date_day, LAG(sale_date_day, 1) OVER (PARTITION BY store_id ORDER BY sale_date_day, id) AS prev_sale_date_day FROM filtered;
